import java.io.*;
import java.util.*;

/**
 * Variant 4: Using BufferedReader, with a different matching approach
 */
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        if (n > m) {
            int t = n;
            n = m;
            m = t;
        }
        long total = (long) n * m;
        if (total < 100) {
            List<Integer>[] g = new List[(int) total];
            for (int i = 0; i < total; i++) {
                g[i] = new ArrayList<>();
            }
            for (int i = 0; i < total; i++) {
                for (int j = 0; j < total; j++) {
                    int r1 = i / m;
                    int c1 = i % m;
                    int r2 = j / m;
                    int c2 = j % m;
                    if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 3) {
                        g[i].add(j);
                    }
                }
            }
            int matchCount = maxMatching(g);
            out.println(matchCount * 2);
        } else {
            long res;
            if (n == 1) {
                res = m / 6 * 6 + (m % 6 == 4 ? 2 : 0) + (m % 6 == 5 ? 4 : 0);
            } else {
                res = (long) n * m;
                res -= res % 2;
            }
            out.println(res);
        }
        out.flush();
    }

    static int maxMatching(List<Integer>[] g) {
        int n = g.length;
        int[] match = new int[n];
        Arrays.fill(match, -1);
        int count = 0;
        for (int u = 0; u < n; u++) {
            boolean[] visited = new boolean[n];
            if (tryMatch(g, match, u, visited))
                count++;
        }
        return count;
    }

    static boolean tryMatch(List<Integer>[] g, int[] match, int u, boolean[] visited) {
        for (int v : g[u]) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] == -1 || tryMatch(g, match, match[v], visited)) {
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
        }
        return false;
    }
}
